//$ids contains a string of comma separated term ids
$idsarray = explode(',', $ids);
$result = db_query("SELECT c.field_classification_tid AS classif, MAX(w.field_hours_worked_value) AS hours, MAX(e.field_merit_reward_value) AS merits
FROM {node} node
LEFT JOIN {field_data_field_project} proj0 ON node.nid = proj0.entity_id AND (proj0.entity_type = 'node' AND proj0.deleted = '0')
LEFT JOIN {node} n0 ON proj0.field_project_target_id = n0.nid
LEFT JOIN {users} u ON node.uid = u.uid
LEFT JOIN {field_data_field_project} proj ON n0.nid = proj.entity_id AND (proj.entity_type = 'node' AND proj.deleted = '0')
LEFT JOIN {node} n1 ON proj.field_project_target_id = n1.nid
LEFT JOIN {field_data_field_classification} c ON node.nid = c.entity_id AND (c.entity_type = 'node' AND c.deleted = '0')
LEFT JOIN {field_data_field_hours_worked} w ON node.nid = w.entity_id AND (w.entity_type = 'node' AND w.deleted = '0')
LEFT JOIN {field_data_field_merit_reward} e ON node.nid = e.entity_id AND (e.entity_type = 'node' AND e.deleted = '0')
WHERE node.status = '1'
AND node.type = 'work_report'
AND c.field_classification_tid IN (:tids)
GROUP BY classif
ORDER BY classif ASC"), array(':tids' => $idsarray);
$resarray = $result->fetchAll();

foreach ($resarray as $row) {
	$term_w = entity_metadata_wrapper('taxonomy_term', taxonomy_term_load($row->classif));
	$term_w->field_max_merits = round($row->merits);
	$term_w->field_max_time = round($row->hours);
	$term_w->save();
}
